  $digest=hash('sha256',json_encode($automation?[$v,$automation]:$v));$old=Run::find($v['id']);if($old){$this->owned($u,$old->id);abort_unless(($old->snapshot['input_digest']??'')===$digest,409,'This generation request already belongs to a different brief.');return $old;}
