 public function owned(User $u,string $id):Run {$this->authorize($u);return Run::where('user_id',$u->id)->where('merchant_key',app(MarketingPosts::class)->merchant())->where('snapshot->mode','free_design')->findOrFail($id);}
 private function verify(Run $r):void {
