  $s=$r->snapshot;$p=$s['product_id']?Product::findOrFail($s['product_id']):null;$b=app(\App\Services\Search\BusinessIdentity::class)->read();abort_unless((!$p||($p->status==='active'&&$p->updated_at?->toIso8601String()===$s['product_updated_at']))&&$b['name']===$s['company'],409,'Product or company facts changed.');
  foreach(array_filter([$s['source'],$s['logo']]) as $asset)abort_unless(is_file($asset['path'])&&hash_equals($asset['sha256'],hash_file('sha256',$asset['path'])),409,'A source image changed.');
  $currentLogo=$b['logo']?app(MarketingPosts::class)->imagePath($b['logo']):null;abort_unless($currentLogo===($s['logo']['path']??null),409,'The company Logo changed.');$this->reference($s['reference']['id'],$s['facts']['type']);
 }
 public function step(User $u,string $id):Run {
  $r=$this->owned($u,$id);$s=$r->snapshot;$status=$r->status;if(!in_array($status,['free_prepared','free_text_completed','free_image_completed','free_save_attention']))return $r;
  $this->verify($r);if(count($s['images'])===$s['facts']['slide_count'])return $this->finish($r);
  $provider=app(MarketingFreePostProvider::class);abort_unless($provider->connection()->version===$s['connection_version'],409,'AI Connect changed. Start a new brief.');$stage=$status==='free_prepared'?'text':'image';$claim=$stage.'_requesting';if(!$this->claim($r,$status,$claim))return $r->fresh();
  $r->refresh();
  try{
   if($stage==='text'){$out=$provider->text($s['facts']);$s['text_result']=['raw'=>mb_substr($out['raw'],0,50000),'completed'=>$out['completed']];$r->update(['snapshot'=>$s]);$receipts=$r->receipts;$receipts['text']=$out['receipt'];$r->update(['receipts'=>$receipts]);abort_unless($out['completed'],409,'Writing response incomplete; usage retained.');$plan=json_decode($out['raw'],true,32,JSON_THROW_ON_ERROR);$this->validatePlan($plan,$s['facts']);if(!empty($s['automation']['intelligence']))app(MarketingCreativeIntelligence::class)->assertFresh($plan,$s['automation']['intelligence']);if(!empty($s['facts']['voucher_terms']))foreach($s['facts']['platforms'] as $platform)$plan['variants'][$platform].="\n\n".$s['facts']['voucher_terms'];$s['facts']['slide_count']=count($plan['slides']);foreach($s['facts']['platforms'] as $platform)$plan['variants'][$platform]=app(MarketingPostCaption::class)->complete($plan['variants'][$platform],$s['facts']['type'],$platform,$s['facts']['cta_destination']??null,$s['facts']['language'],$s['facts']['custom_cta']??false);$r->update(['creative'=>$plan,'snapshot'=>$s,'status'=>'free_text_completed']);}
   else{$n=count($s['images']);$paths=isset($s['products'])?array_column(array_column($s['products'],'source'),'path'):[$s['source']['path']];if($s['logo'])$paths[]=$s['logo']['path'];$paths=array_merge($paths,$s['reference']['paths']);$out=$provider->image($s['facts'],$r->creative['slides'][$n],$paths);$receipts=$r->receipts;$receipts['image_'.($n+1)]=$out['receipt'];$r->update(['receipts'=>$receipts]);$bytes=is_string($out['encoded'])&&strlen($out['encoded'])<=15000000?base64_decode($out['encoded'],true):false;$info=is_string($bytes)?@getimagesizefromstring($bytes):false;abort_unless($info&&$info['mime']==='image/png'&&$info[0]===1024&&$info[1]===1280&&strlen($bytes)<=10485760,409,'Invalid image output.');
