 }
 private function claim(Run $r,string $expected,string $next):bool {return (bool)Run::whereKey($r->id)->where('status',$expected)->whereJsonLength('snapshot->images',count($r->snapshot['images']))->update(['status'=>$next]);}
 private function validatePlan($p,array $f):void {
