 private function percentages(string $text):array {preg_match_all('/(?<![\d.])(\d+(?:\.\d+)?)\s*[%％]/u',$text,$matches);return array_values(array_unique(array_map(fn($n)=>(string)(float)$n,$matches[1])));}
 private function finish(Run $r):Run {
