 }
 public function view(Run $r):array {return ['id'=>$r->id,'status'=>$r->status,'completed_images'=>count($r->snapshot['images']),'total_images'=>$r->snapshot['facts']['slide_count'],'product_id'=>$r->snapshot['product_id'],'product_ids'=>$r->snapshot['product_ids']??[$r->snapshot['product_id']],'product_title'=>$r->snapshot['title'],'can_save'=>$r->status==='free_save_attention','can_step'=>in_array($r->status,['free_prepared','free_text_completed','free_image_completed'],true),'review_url'=>url('/admin/marketing/daily-drafts/'.$r->id),'error'=>$r->error_code,'post_ids'=>$r->post_ids];}
